      heading: "Treatment: calcium, vitamin D and the antiresorptive drugs",
      points: [
        "**Correct vitamin D before starting any antiresorptive drug.** For deficiency, cholecalciferol 60,000 IU orally once weekly for 8 weeks, then 60,000 IU once monthly as maintenance; recheck the 25-hydroxyvitamin D at 3 months aiming for 30 ng/mL or above. Calcifediol or an active analogue such as alfacalcidol is reserved for renal or hepatic failure, where hydroxylation fails.",
        "**Total calcium intake of 1000-1200 mg daily, diet first**: 250 mL of milk gives about 300 mg, a cup of curd about 275 mg, 100 g of ragi about 350 mg, and 100 g of sesame or paneer are useful additions. Supplement only the shortfall, usually elemental calcium 500 mg once or twice daily as calcium carbonate with food, or calcium citrate if the patient is on a proton pump inhibitor or has had gastric surgery.",
        "**First-line drug therapy is an oral bisphosphonate - alendronate 70 mg once weekly or risedronate 35 mg once weekly** - taken on an empty stomach on waking with a full glass of plain water, remaining upright and fasting for 30 minutes. This administration instruction is itself an examination mark: failing it causes oesophagitis and destroys absorption, which is under 1% at best.",
        "**Zoledronic acid 5 mg intravenously once a year over at least 15 minutes** is the choice when oral drugs are not tolerated, adherence is poor, or after a hip fracture, where it reduces mortality; pre-hydrate, ensure vitamin D repletion and warn about a self-limiting acute-phase reaction with fever and myalgia in about 30% after the first dose, treated with paracetamol.",
        "**Denosumab 60 mg subcutaneously every 6 months** is used in renal impairment (it is not cleared renally and is usable down to an eGFR of 15-30 with careful calcium monitoring) and in bisphosphonate failure; the critical teaching point is that **stopping denosumab causes rebound bone loss and multiple vertebral fractures within months, so it must never be simply discontinued** - a bisphosphonate must follow.",
        "**Teriparatide 20 micrograms subcutaneously daily for up to 24 months is the anabolic option** for severe osteoporosis with multiple vertebral fractures, very low T-scores or failure on antiresorptives, and it must always be followed by an antiresorptive to lock in the gain; it is contraindicated in Paget disease, unexplained high alkaline phosphatase, prior skeletal irradiation and hypercalcaemia. Menopausal hormone therapy and raloxifene 60 mg daily are second-line options in younger postmenopausal women, both raising thromboembolic risk.",
      ],
